CREATE SET TABLE MDP01_META.META_LINEAGE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      lineage_id INTEGER NOT NULL,      source_table_id INTEGER NOT NULL,      target_table_id INTEGER NOT NULL,      transformation_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      transformation_logic VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      etl_tool VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      etl_job_name VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      etl_schedule VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC,      dependency_level INTEGER,      comment_string VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( lineage_id )INDEX ( source_table_id )INDEX ( target_table_id );